# owner: platform
import unittest

from hourglass.errors import OutsideHoursError
from hourglass.gaps import find_gaps
from hourglass.parsing import parse_span

OPENING = parse_span("09:00-17:00")


# ---
def gaps_for(*texts):
    return find_gaps([parse_span(text) for text in texts], OPENING)


class FindGapsTests(unittest.TestCase):
    def test_lunch_gap(self):
        result = gaps_for("09:00-12:00", "13:00-17:00")
        self.assertEqual(result, ["gap 12:00-13:00 (60 min)"])

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(gaps_for("09:00-13:00", "12:00-17:00"), [])

    def test_touching_spans_leave_no_gap(self):
        self.assertEqual(gaps_for("09:00-12:00", "12:00-17:00"), [])

    def test_nobody_worked(self):
        self.assertEqual(gaps_for(), ["gap 09:00-17:00 (480 min)"])

    def test_edges_and_order(self):
        result = gaps_for("14:00-15:00", "10:00-12:30")
        self.assertEqual(len(result), 3)
        self.assertEqual(result[0], "gap 09:00-10:00 (60 min)")
        self.assertEqual(result[1], "gap 12:30-14:00 (90 min)")
        self.assertEqual(result[2], "gap 15:00-17:00 (120 min)")

    def test_early_start_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for("08:30-12:00")

    def test_late_end_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for("09:00-10:00", "16:00-17:30")


if __name__ == "__main__":
    unittest.main()
